    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    yesterday_bids = []
    rich_threat = 0
    urgent_opp = 0
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 2:
                rich_threat += 1
            if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    slots = max(1, int(supply // WATER_REQ))
    crowd = len(alive) + 1
    scarcity = crowd - slots

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    need_score = 0
    if hp <= 2:
        need_score += 4
    elif hp <= 4:
        need_score += 3
    elif hp <= 6:
        need_score += 2
    else:
        need_score += 1

    if no_water >= 2:
        need_score += 4
    elif no_water >= 1:
        need_score += 2

    if supply <= 16:
        need_score += 2
    elif supply <= 19:
        need_score += 1

    if scarcity >= 3:
        need_score += 3
    elif scarcity >= 2:
        need_score += 2
    elif scarcity >= 1:
        need_score += 1

    if rich_threat >= 1:
        need_score += 1
    if urgent_opp >= 2:
        need_score += 1

    if need_score <= 2:
        base = 16.0
    elif need_score <= 4:
        base = 28.0
    elif need_score <= 6:
        base = 46.0
    elif need_score <= 8:
        base = 68.0
    else:
        base = 92.0

    if highest_prev >= 120:
        if hp >= 7 and no_water == 0:
            bid = 12.0
        else:
            bid = max(base, 74.0)
    elif highest_prev >= 90:
        if hp >= 8 and no_water == 0 and supply >= 20:
            bid = 15.0
        else:
            bid = max(base, min(highest_prev + 2.0, 78.0))
    else:
        target = max(avg_prev + 3.0, base)
        bid = target

    if day >= 8:
        bid += 8.0
    elif day >= 6 and (hp <= 5 or no_water >= 1):
        bid += 5.0

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.9 + 2.0)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(0.95 * DAILY_SALARY, budget))

