    prev_eric = eric.get('previous_trace') if eric else None
    eric_bid = prev_eric.get('bid', 0) if prev_eric else 0

    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], DAILY_SALARY * 0.9))

